fn reverse(a: Vec<char>) -> Vec<char> {
    // Create a new vector with the same capacity as `a`.
    let mut b = Vec::with_capacity(a.len());

    // Loop over a.iter().rev(), pushing into `b`.
    // We keep two invariants:
    //  1) b.len() never exceeds a.len()
    //  2) for all j < b.len(), b[j] == a[a.len()-1-j]
    // We use a decreases-measure of (a.len() - b.len()) to prove termination.
    #[invariant(b.len() <= a.len())]
    #[invariant(forall(|j: usize| j < b.len() ==>
         b[j] == a[a.len() - 1 - j]))]
    #[decreases(a.len() - b.len())]
    for ch in a.iter().rev() {
        b.push(*ch);
    }

    b
}

